#!/usr/bin/env bash
# macOS/Linux/WSL version of local-up.ps1. Usage: ./scripts/local-up.sh you@vsmgrowth.com "Your Name"
set -euo pipefail
docker info >/dev/null 2>&1 || { echo "Docker is not running."; exit 1; }
[ -d node_modules ] || npm install
npx supabase@latest start
eval "$(npx supabase@latest status -o env | sed 's/^/export /')"
TARGET=.env.local; [ -f .env.local ] && TARGET=.env.docker.local
cat > "$TARGET" <<ENV
# Generated by scripts/local-up.sh for the LOCAL Docker stack only.
NEXT_PUBLIC_SUPABASE_URL=${API_URL}
NEXT_PUBLIC_SUPABASE_ANON_KEY=${ANON_KEY}
SUPABASE_SERVICE_ROLE_KEY=${SERVICE_ROLE_KEY}
APP_URL=http://localhost:3000
ORG_SLUG=vsm-growth
CRON_SECRET=local-$RANDOM$RANDOM
DEMO_EMAIL_DOMAIN=demo.vsmgrowth.com
ENV
echo "▸ Local keys written to $TARGET (an existing .env.local is never overwritten)"
[ -n "${1:-}" ] && node scripts/local-bootstrap.mjs --email "$1" --name "${2:-Super Admin}"
echo "Studio http://127.0.0.1:54323 · Mail http://127.0.0.1:54324 · App: npm run dev"
